// Convierte la respuesta base64url de Gmail API a binario n8n
const base64url = $json.data || '';
if (!base64url) throw new Error('Gmail API devolvió data vacía para el adjunto Excel.');

// base64url → base64 estándar
const base64 = base64url.replace(/-/g, '+').replace(/_/g, '/');
const buffer = Buffer.from(base64, 'base64');

const excelInfo = $node["Extraer IDs de Adjuntos"].json;
const fileName  = excelInfo.excelFileName || 'adjunto.xlsx';
const mimeType  = excelInfo.excelMimeType || 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet';

const binaryData = await this.helpers.prepareBinaryData(buffer, fileName, mimeType);

return [{
  json: {
    messageId:    excelInfo.messageId,
    emailFrom:    excelInfo.emailFrom,
    emailSubject: excelInfo.emailSubject,
    hasExcel:     true,
    hasZip:       excelInfo.hasZip,
    excelFileName: fileName
  },
  binary: { excelFile: binaryData }
}];

const items = $input.all();
const REQUIRED = ['OBLIGACION', 'CEDULA', 'NOMBRE', 'CAPITAL', 'INTERES'];

if (!items || items.length === 0) {
  return [{ json: { isValid: false, validationError: 'El Excel no tiene datos en Hoja2.', rows: [], rowCount: 0 } }];
}

const validRows = items.map(i => i.json).filter(r => Object.values(r).some(v => v !== null && v !== undefined && v !== ''));

if (validRows.length === 0) {
  return [{ json: { isValid: false, validationError: 'Todas las filas de Hoja2 están vacías.', rows: [], rowCount: 0 } }];
}

const cols = Object.keys(validRows[0]);
const missing = REQUIRED.filter(c => !cols.includes(c));

if (missing.length > 0) {
  return [{ json: { isValid: false, validationError: `Columnas faltantes: ${missing.join(', ')}. Detectadas: ${cols.slice(0, 10).join(', ')}`, rows: [], rowCount: 0 } }];
}

return [{ json: { isValid: true, rows: validRows, rowCount: validRows.length, columns: cols } }];

const rows = $json.rows;
const MESES = ['enero','febrero','marzo','abril','mayo','junio','julio','agosto','septiembre','octubre','noviembre','diciembre'];
const hoy = new Date();
const fechaHoy = `${hoy.getDate()} de ${MESES[hoy.getMonth()]} del ${hoy.getFullYear()}`;

const fmt = (val) => {
  if (val === null || val === undefined || val === '') return '';
  const n = parseFloat(String(val).replace(/[^0-9.-]/g, ''));
  return isNaN(n) ? String(val) : n.toLocaleString('es-CO');
};

const fmtFecha = (val) => {
  if (!val) return '';
  try {
    const d = new Date(val);
    if (!isNaN(d.getTime())) return `${d.getDate()} de ${MESES[d.getMonth()]} del ${d.getFullYear()}`;
  } catch(e) {}
  return String(val);
};

return rows.map(row => ({ json: {
  'FECHA DE ASIGNACION':                fechaHoy,
  'TIPO DE JUZGADO':                    'PROMISCUO MUNICIPAL',
  'CIUDAD DE JUZGADO':                  '',
  'CUANTIA':                            'MINIMA',
  'OBLIGACION':                         row.OBLIGACION || '',
  'IDENTIFICACION':                     row.CEDULA || '',
  'NOMBRE':                             row.NOMBRE || '',
  'CAPITAL':                            fmt(row.CAPITAL),
  'INTERES':                            fmt(row.INTERES),
  'FECHA MORA':                         fmtFecha(row.MORA),
  'FECHA DE SUSCRIPCION':               '',
  'VALOR CUANTIA':                      fmt(row['TOTAL INTERES'] || row.TOTAL || ''),
  'DIRECCION DE RESIDENCIA':            '',
  'DIRECCION ELECTRONICA':              '',
  'NIT EMPRESA TT':                     '',
  'NOMBRE EMPRESA TT':                  '',
  'DIRECCION ELECTRONICA EMPLEADOR':    '',
  'PLACA':                              '',
  'SERVICIO':                           '',
  'CLASE':                              '',
  'MARCA':                              '',
  'LINEA':                              '',
  'MODELO':                             '',
  'COLOR':                              '',
  'SERIE':                              '',
  'MOTOR':                              '',
  'CHASIS':                             '',
  'TIPO DE CARROCERIA':                 '',
  'STRIA MCPAL\nTTOyTTE':               '',
  'DIRECCION ELECTRONICA DEL TRANSITO': ''
}}));

const base64url = $json.data || '';
if (!base64url) throw new Error('Gmail API devolvió data vacía para el adjunto ZIP.');

const base64 = base64url.replace(/-/g, '+').replace(/_/g, '/');
const buffer = Buffer.from(base64, 'base64');

const zipInfo  = $node["Extraer IDs de Adjuntos"].json;
const fileName = zipInfo.zipFileName || 'adjunto.zip';
const mimeType = zipInfo.zipMimeType || 'application/zip';

const binaryData = await this.helpers.prepareBinaryData(buffer, fileName, mimeType);

return [{
  json: {
    messageId:    zipInfo.messageId,
    emailFrom:    zipInfo.emailFrom,
    emailSubject: zipInfo.emailSubject,
    zipFileName:  fileName
  },
  binary: { zipFile: binaryData }
}];
